-- RANGE: por mês
CREATE TABLE events (id BIGINT, created_at TIMESTAMP, ...)
PARTITION BY RANGE (created_at);

CREATE TABLE events_2026_01 PARTITION OF events
  FOR VALUES FROM ('2026-01-01') TO ('2026-02-01');
CREATE TABLE events_2026_02 PARTITION OF events
  FOR VALUES FROM ('2026-02-01') TO ('2026-03-01');

-- pg_partman automatiza creation de novas partitions
CREATE EXTENSION pg_partman;
SELECT partman.create_parent('public.events', 'created_at', 'range', 'monthly');

-- Cleanup instantâneo
DROP TABLE events_2025_01;  -- data de 2025 jan some em 50ms

CREATE TABLE users (id BIGINT, ...) PARTITION BY HASH (id);

CREATE TABLE users_0 PARTITION OF users FOR VALUES WITH (MODULUS 4, REMAINDER 0);
CREATE TABLE users_1 PARTITION OF users FOR VALUES WITH (MODULUS 4, REMAINDER 1);
CREATE TABLE users_2 PARTITION OF users FOR VALUES WITH (MODULUS 4, REMAINDER 2);
CREATE TABLE users_3 PARTITION OF users FOR VALUES WITH (MODULUS 4, REMAINDER 3);

-- Inserts distribuem uniformemente
